def transform(grid):
    if not grid or not grid[0]: return grid

    H, W = len(grid), len(grid[0])

    # Helper to find frame
    def find_frame_color(target_colors):
        for c in target_colors:
            coords = []
            for r in range(H):
                for col_idx in range(W):
                    if grid[r][col_idx] == c:
                        coords.append((r, col_idx))

            if not coords: continue

            r_min, r_max = min(r for r, _ in coords), max(r for r, _ in coords)
            c_min, c_max = min(c for _, c in coords), max(c for _, c in coords)

            # Check if border is solid
            is_frame = True
            for r in range(r_min, r_max + 1):
                for col_idx in range(c_min, c_max + 1):
                    on_border = (r == r_min or r == r_max or col_idx == c_min or col_idx == c_max)
                    if on_border:
                        if grid[r][col_idx] != c:
                            is_frame = False
                            break
                if not is_frame: break

            if is_frame:
                return c, r_min, r_max, c_min, c_max
        return None

    result = find_frame_color(range(1, 10))
    if not result:
        # Fallback if no frame found, check for 2s (Test Input specific) or return input
        # But we use the logic above which handles dynamic colors.
        return grid

    target_color, r_min, r_max, c_min, c_max = result
    frame_width = c_max - c_min + 1

    # Copy frame pattern to left side
    for r in range(r_min, r_max + 1):
        # Copy from (c_min to c_max) to (0 to frame_width-1)
        for c in range(frame_width):
            src_col = c_min + c
            if src_col < W:
                grid[r][c] = grid[r][src_col]

    return grid
